//! Parity tests for `gpt_sovits_text::tone_sandhi` against golden fixtures
//! generated by `parity/tone_sandhi/gen_fixtures.py`.
//!
//! `_split_word` calls `jieba_fast.cut_for_search`. The fixtures record its
//! Python output for every word, and all tests except the `*_with_jieba` ones
//! run `ToneSandhi` with `cut_for_search` replaced by a lookup in that record,
//! so they check the tone sandhi logic independently of jieba parity. The
//! `*_with_jieba` tests use the real `jieba_fast` port and report its parity
//! separately.

use std::collections::HashMap;
use std::sync::{Arc, LazyLock};

use gpt_sovits_text::tone_sandhi::{IndexError, Seg, ToneSandhi, py_isnumeric};
use serde_json::{Value, json};

const PRE_MERGE: &str = include_str!("fixtures/tone_sandhi/pre_merge.jsonl");
const MODIFIED_TONE: &str = include_str!("fixtures/tone_sandhi/modified_tone.jsonl");
const UNITS: &str = include_str!("fixtures/tone_sandhi/units.jsonl");
const SPLIT_WORD: &str = include_str!("fixtures/tone_sandhi/split_word.jsonl");

/// Words whose `_split_word` result with the real `jieba_fast` port differs
/// from Python (documented in `parity/tone_sandhi/README.md`).
///
/// Empty: the `jieba_fast` port matches Python `jieba_fast.cut_for_search` on
/// every word of `split_word.jsonl`. (The jieba-rs wrapper that the port
/// replaced split 208 runs of characters that are not in the dictionary, such
/// as `仳涏`, into single characters; Python keeps each run as one HMM word.)
/// The `*_with_jieba` tests fail on any mismatch outside this list and print
/// the listed words that match now.
const KNOWN_SPLIT_WORD_MISMATCHES: &[&str] = &[];

fn lines(src: &str) -> Vec<Value> {
  src
    .lines()
    .filter(|l| !l.is_empty())
    .map(|l| serde_json::from_str(l).unwrap())
    .collect()
}

static CFS: LazyLock<Arc<HashMap<String, Vec<String>>>> = LazyLock::new(|| {
  Arc::new(
    lines(SPLIT_WORD)
      .into_iter()
      .map(|c| {
        (
          c["i"].as_str().unwrap().to_string(),
          serde_json::from_value(c["cfs"].clone()).unwrap(),
        )
      })
      .collect(),
  )
});

/// `ToneSandhi` whose `jieba.cut_for_search` is the recorded Python output.
fn recorded() -> ToneSandhi {
  let cfs = Arc::clone(&CFS);
  let mut ts = ToneSandhi::new();
  ts.cut_for_search = Box::new(move |word| {
    cfs
      .get(word)
      .unwrap_or_else(|| panic!("no recorded cut_for_search for {word:?}"))
      .clone()
  });
  ts
}

fn strs(v: &Value) -> Vec<String> {
  serde_json::from_value(v.clone()).unwrap()
}

/// A seg from the flat fixture form `[word0, pos0, word1, pos1, ...]`.
fn seg(v: &Value) -> Seg {
  let flat = strs(v);
  flat
    .chunks(2)
    .map(|p| (p[0].clone(), p[1].clone()))
    .collect()
}

/// A seg in the flat fixture form.
fn seg_json(s: &Seg) -> Value {
  Value::Array(s.iter().flat_map(|(w, p)| [json!(w), json!(p)]).collect())
}

fn res<T: serde::Serialize>(r: Result<T, IndexError>) -> Value {
  match r {
    Ok(v) => json!({ "o": v }),
    Err(IndexError(m)) => json!({ "e": ["IndexError", m] }),
  }
}

fn want(case: &Value) -> Value {
  match case.get("o") {
    Some(o) => json!({ "o": o }),
    None => json!({ "e": case["e"] }),
  }
}

fn report(name: &str, n: usize, bad: &[String]) {
  eprintln!("{name}: {}/{n} exact matches", n - bad.len());
}

/// The merge steps that `pre_merge_for_modify` reports as failed (it prints
/// `"<name> failed"`), computed with the individual Rust methods.
fn failed_steps(ts: &ToneSandhi, input: &Seg) -> Vec<&'static str> {
  let mut failed = Vec::new();
  let mut s = ts._merge_bu(input);
  match ts._merge_yi(&s) {
    Ok(v) => s = v,
    Err(_) => failed.push("_merge_yi"),
  }
  s = ts._merge_reduplication(&s);
  match ts._merge_continuous_three_tones(&s) {
    Ok(v) => s = v,
    Err(_) => failed.push("_merge_continuous_three_tones"),
  }
  if ts._merge_continuous_three_tones_2(&s).is_err() {
    failed.push("_merge_continuous_three_tones_2");
  }
  failed
}

#[test]
fn pre_merge_for_modify() {
  let ts = recorded();
  let cases = lines(PRE_MERGE);
  let mut bad = Vec::new();
  for c in &cases {
    let input = seg(&c["i"]);
    let got = seg_json(&ts.pre_merge_for_modify(&input));
    let got_failed = json!(failed_steps(&ts, &input));
    if got != c["o"] || got_failed != c["f"] {
      if bad.len() < 20 {
        eprintln!(
          "mismatch for {}:\n  want {} {}\n  got  {got} {got_failed}",
          c["i"], c["o"], c["f"]
        );
      }
      bad.push(c["i"].to_string());
    }
  }
  report("pre_merge_for_modify", cases.len(), &bad);
  assert!(cases.len() > 5000);
  assert!(bad.is_empty(), "{} mismatches", bad.len());
}

#[test]
fn modified_tone() {
  let ts = recorded();
  let cases = lines(MODIFIED_TONE);
  let mut bad = Vec::new();
  for c in &cases {
    let got = res(ts.modified_tone(
      c["w"].as_str().unwrap(),
      c["p"].as_str().unwrap(),
      strs(&c["f"]),
    ));
    if got != want(c) {
      if bad.len() < 20 {
        eprintln!(
          "mismatch for {} {} {}:\n  want {}\n  got  {got}",
          c["w"],
          c["p"],
          c["f"],
          want(c)
        );
      }
      bad.push(c["w"].to_string());
    }
  }
  report("modified_tone", cases.len(), &bad);
  assert!(bad.is_empty(), "{} mismatches", bad.len());
}

fn run_unit(ts: &ToneSandhi, name: &str, a: &[Value]) -> Value {
  let s = |i: usize| a[i].as_str().unwrap();
  match name {
    "_bu_sandhi" => res(ts._bu_sandhi(s(0), strs(&a[1]))),
    "_yi_sandhi" => res(ts._yi_sandhi(s(0), strs(&a[1]))),
    "_neural_sandhi" => res(ts._neural_sandhi(s(0), s(1), strs(&a[2]))),
    "_three_sandhi" => res(ts._three_sandhi(s(0), strs(&a[1]))),
    "_split_word" => res(ts._split_word(s(0))),
    "_is_reduplication" => json!({ "o": ts._is_reduplication(s(0)) }),
    "_all_tone_three" => res(ts._all_tone_three(&strs(&a[0]))),
    "_merge_bu" => json!({ "o": seg_json(&ts._merge_bu(&seg(&a[0]))) }),
    "_merge_yi" => res(ts._merge_yi(&seg(&a[0])).map(|s| seg_json(&s))),
    "_merge_reduplication" => json!({ "o": seg_json(&ts._merge_reduplication(&seg(&a[0]))) }),
    "_merge_continuous_three_tones" => res(
      ts._merge_continuous_three_tones(&seg(&a[0]))
        .map(|s| seg_json(&s)),
    ),
    "_merge_continuous_three_tones_2" => res(
      ts._merge_continuous_three_tones_2(&seg(&a[0]))
        .map(|s| seg_json(&s)),
    ),
    "_merge_er" => json!({ "o": seg_json(&ts._merge_er(&seg(&a[0]))) }),
    _ => panic!("unknown unit {name}"),
  }
}

#[test]
fn units() {
  let ts = recorded();
  let cases = lines(UNITS);
  let mut per_fn: HashMap<String, (usize, usize)> = HashMap::new();
  let mut bad = Vec::new();
  for c in &cases {
    let name = c["fn"].as_str().unwrap();
    let got = run_unit(&ts, name, c["a"].as_array().unwrap());
    let e = per_fn.entry(name.to_string()).or_default();
    e.0 += 1;
    if got != want(c) {
      if bad.len() < 20 {
        eprintln!(
          "mismatch for {name}{}:\n  want {}\n  got  {got}",
          c["a"],
          want(c)
        );
      }
      bad.push(format!("{name}{}", c["a"]));
    } else {
      e.1 += 1;
    }
  }
  let mut names: Vec<_> = per_fn.into_iter().collect();
  names.sort();
  for (name, (n, ok)) in &names {
    eprintln!("{name}: {ok}/{n}");
  }
  report("units", cases.len(), &bad);
  assert_eq!(names.len(), 13, "every method has unit cases");
  assert!(bad.is_empty(), "{} mismatches", bad.len());
}

/// `_split_word` with the recorded `cut_for_search`: checks the port of the
/// sort and split logic alone.
#[test]
fn split_word_recorded() {
  let ts = recorded();
  let cases = lines(SPLIT_WORD);
  let mut bad = Vec::new();
  for c in &cases {
    let got = res(ts._split_word(c["i"].as_str().unwrap()));
    if got != want(c) {
      eprintln!("mismatch for {}: want {} got {got}", c["i"], want(c));
      bad.push(c["i"].to_string());
    }
  }
  report("_split_word (recorded cut_for_search)", cases.len(), &bad);
  assert!(bad.is_empty(), "{} mismatches", bad.len());
}

/// `_split_word` with the real `jieba_fast` port. Its parity depends on
/// `jieba_fast::cut_for_search`; every mismatching word must be in
/// `KNOWN_SPLIT_WORD_MISMATCHES`.
#[test]
fn split_word_with_jieba() {
  let ts = ToneSandhi::new();
  let cases = lines(SPLIT_WORD);
  let mut cfs_bad = 0;
  let mut bad = Vec::new();
  for c in &cases {
    let word = c["i"].as_str().unwrap();
    if jieba_fast::cut_for_search(word, true) != strs(&c["cfs"]) {
      cfs_bad += 1;
    }
    let got = res(ts._split_word(word));
    if got != want(c) {
      bad.push(word.to_string());
      assert!(
        KNOWN_SPLIT_WORD_MISMATCHES.contains(&word),
        "new _split_word mismatch for {word}: want {} got {got}",
        want(c)
      );
    }
  }
  eprintln!(
    "cut_for_search (jieba_fast port): {}/{} exact matches",
    cases.len() - cfs_bad,
    cases.len()
  );
  report("_split_word (jieba_fast port)", cases.len(), &bad);
  let fixed: Vec<_> = KNOWN_SPLIT_WORD_MISMATCHES
    .iter()
    .filter(|w| !bad.iter().any(|b| b == *w))
    .collect();
  if !fixed.is_empty() {
    eprintln!(
      "{} known mismatches match now; remove them from KNOWN_SPLIT_WORD_MISMATCHES: {fixed:?}",
      fixed.len()
    );
  }
}

/// `modified_tone` end to end with the real `jieba_fast` port. Every mismatch
/// must be a word in `KNOWN_SPLIT_WORD_MISMATCHES`.
#[test]
fn modified_tone_with_jieba() {
  let ts = ToneSandhi::new();
  let cases = lines(MODIFIED_TONE);
  let mut bad = 0;
  for c in &cases {
    let word = c["w"].as_str().unwrap();
    let got = res(ts.modified_tone(word, c["p"].as_str().unwrap(), strs(&c["f"])));
    if got != want(c) {
      bad += 1;
      assert!(
        KNOWN_SPLIT_WORD_MISMATCHES.contains(&word),
        "mismatch for {word} that is not a known _split_word mismatch: want {} got {got}",
        want(c)
      );
    }
  }
  eprintln!(
    "modified_tone (jieba_fast port): {}/{} exact matches",
    cases.len() - bad,
    cases.len()
  );
}

#[test]
fn isnumeric_table() {
  for ch in [
    '0', '9', '一', '二', '零', '〇', '百', '千', '万', '亿', '½', '①', 'Ⅻ', '٣',
  ] {
    assert!(py_isnumeric(ch), "{ch}");
  }
  for ch in ['a', '两', '个', '第', '，', ' ', '.'] {
    assert!(!py_isnumeric(ch), "{ch}");
  }
}
